class HarmonicRibbon3D(ThreeDScene):
    def construct(self):
        axes = ThreeDAxes()
        self.add(axes)
        self.set_camera_orientation(phi=65*DEGREES, theta=45*DEGREES)
        def curve(t):
            x = np.sin(2*t) + 0.3*np.sin(5*t)
            y = np.cos(3*t) + 0.3*np.cos(7*t)
            z = 0.6*np.sin(4*t)
            return np.array([x, y, z])
        graph = ParametricFunction(curve, t_range=[0, 20], color=YELLOW)
        self.play(Create(graph, rate_func=linear), run_time=6)

class ThreeDParametricSpring(ThreeDScene):
    def construct(self):
        curve = ParametricFunction(
            lambda t: np.array([np.cos(2*t), np.sin(2*t), t/4]),
            t_range=[0, 8*PI],
            color=BLUE,
        )
        self.set_camera_orientation(phi=70*DEGREES, theta=30*DEGREES)
        self.play(Create(curve), run_time=4)
        self.wait(1)
